/* vlr core: the `vapor` table over the platform interface. No OS headers here. */
#include <stdio.h>
#if defined(VLR_HOSTLIBDIR) && defined(__NuttX__)
#include <sys/mount.h>
#include <sys/stat.h>
#endif
#include <errno.h>
#include <stdlib.h>
#include <string.h>

#include "lauxlib.h"
#include "lualib.h"
#include "vlr.h"
#include "vlr_platform.h"

extern const char *const vlr_builtin[]; /* NULL-terminated names of the compiled-in modules, same source */
extern int vlr_dotzero; /* patched into lobject.c, see patches/ */

/* generated by tools/embed from the lua/ directory */
extern const unsigned char vlr_lua_compat[], vlr_lua_sched[];
extern const unsigned int vlr_lua_compat_len, vlr_lua_sched_len;

/*
 * Garbage collector pacing. Lua's defaults (pause 200, stepmul 100) let the heap grow to twice the live data before
 * collecting, which does not fit a 264 KB chip: the RP2040 build sets 100/400 (collect as soon as garbage equals live
 * data), as vlua does. Cost measured with vlua there: string-building benchmark 0.8 s -> 4.8 s, others unchanged.
 */
#ifndef VLR_GC_PAUSE
#define VLR_GC_PAUSE 200
#endif
#ifndef VLR_GC_STEPMUL
#define VLR_GC_STEPMUL 100
#endif

/*
 * os.exit that closes the state first. Lua's own skips lua_close unless asked to, and on NuttX a task's heap is not
 * reclaimed at exit (one shared heap), so every script ending in os.exit() leaked its whole Lua state until reboot.
 */
static int l_exit(lua_State *L)
{
    int status;

    if (lua_isboolean(L, 1)) status = lua_toboolean(L, 1) ? EXIT_SUCCESS : EXIT_FAILURE;
    else status = (int)luaL_optinteger(L, 1, EXIT_SUCCESS);
    lua_close(L);
    vlr_flush(); /* the wasm build does not run exit()'s stdio flush: a partial last line would be lost */
    exit(status);
}

/* os.execute goes through the platform. Returns what luaL_execresult expects for this Lua build. */
int vlr_lua_system(const char *cmd)
{
    int r;

    if (cmd == NULL) return vlr_exec(NULL);
    errno = 0;
    r = vlr_exec(cmd);
    if (r < 0) {
        if (errno == 0) errno = ENOSYS;
        return -1;
    }
    errno = 0; /* the command ran: stale errno from the spawn must not make lauxlib report a failure */
#ifdef LUA_USE_POSIX
    return r << 8; /* a wait status: lauxlib decodes it with WEXITSTATUS */
#else
    return r;
#endif
}

static int l_now(lua_State *L)
{
    lua_pushinteger(L, (lua_Integer)vlr_now_ms());
    return 1;
}

/* vapor.wait(fds, timeout_ms) -> array of ready fds ({} on timeout); timeout nil = forever */
static int l_wait(lua_State *L)
{
    int fds[VLR_MAX_FDS], ready[VLR_MAX_FDS], n, i, r, k = 0;
    int timeout = lua_isnoneornil(L, 2) ? -1 : (int)luaL_checkinteger(L, 2);

    luaL_checktype(L, 1, LUA_TTABLE);
    n = (int)lua_rawlen(L, 1);
    luaL_argcheck(L, n <= VLR_MAX_FDS, 1, "too many fds");
    for (i = 0; i < n; i++) {
        lua_rawgeti(L, 1, i + 1);
        fds[i] = (int)luaL_checkinteger(L, -1);
        lua_pop(L, 1);
    }
    r = vlr_wait(fds, n, ready, timeout);
    if (r < 0) {
        lua_pushnil(L);
        lua_pushstring(L, vlr_last_error());
        return 2;
    }
    lua_createtable(L, n, 0);
    for (i = 0; i < n; i++) {
        if (ready[i]) {
            lua_pushinteger(L, fds[i]);
            lua_rawseti(L, -2, ++k);
        }
    }
    return 1;
}

static void setcaps(lua_State *L)
{
    static const struct { const char *name; uint32_t bit; } caps[] = {
        {"fs", VLR_CAP_FS}, {"net", VLR_CAP_NET}, {"gfx", VLR_CAP_GFX}, {"tty", VLR_CAP_TTY},
        {"dlopen", VLR_CAP_DLOPEN}, {"exec", VLR_CAP_EXEC},
    };
    uint32_t have = vlr_caps();
    const char *const *b;
    size_t i;

    for (b = vlr_builtin, have &= ~(uint32_t)VLR_CAP_NET; *b != NULL; b++) {
        if (strcmp(*b, "vapor.net") == 0) have |= vlr_caps() & VLR_CAP_NET; /* a capability needs the platform AND the module */
    }

    lua_newtable(L);
    for (i = 0; i < sizeof caps / sizeof caps[0]; i++) {
        lua_pushboolean(L, (have & caps[i].bit) != 0);
        lua_setfield(L, -2, caps[i].name);
    }
    lua_setfield(L, -2, "caps");
}

#ifndef VLR_STRIP_INTERNAL
#define VLR_STRIP_INTERNAL 0
#endif

#if VLR_STRIP_INTERNAL
/* round trip through a stripped dump: drops line info and local names of our own Lua code (about 40% of what a
   function costs in RAM); the cost is that errors inside the scheduler show no line numbers */
static int strip(lua_State *L, const char *name)
{
    size_t len;
    const char *bytes;

    lua_getglobal(L, "string");
    lua_getfield(L, -1, "dump");
    lua_remove(L, -2);
    lua_pushvalue(L, -2);
    lua_pushboolean(L, 1);
    lua_call(L, 2, 1); /* string.dump(fn, true) */
    bytes = lua_tolstring(L, -1, &len);
    if (luaL_loadbufferx(L, bytes, len, name, "b") != LUA_OK) return 1;
    lua_remove(L, -2); /* the dump string */
    lua_remove(L, -2); /* the unstripped function */
    return 0;
}
#endif

/* loads an embedded Lua chunk (stripped when VLR_STRIP_INTERNAL) and leaves the function on the stack; used by the
   generated module registry for Lua-file modules */
int vlr_load_embedded(lua_State *L, const unsigned char *src, size_t len, const char *name)
{
    if (luaL_loadbuffer(L, (const char *)src, len, name)) return 1;
#if VLR_STRIP_INTERNAL
    if (strip(L, name)) return 1;
#endif
    return 0;
}

static int runembedded(lua_State *L, const unsigned char *src, unsigned int len, const char *name)
{
    if (vlr_load_embedded(L, src, len, name)) return 1;
    return lua_pcall(L, 0, 0, 0);
}

void vlr_modules_open(lua_State *L); /* generated from modules.conf */

#ifndef VLR_VERSION
#define VLR_VERSION "0.2.0"
#endif

#if defined(__EMSCRIPTEN__)
#define VLR_PLATFORM "wasm"
#elif defined(_WIN32)
#define VLR_PLATFORM "windows"
#elif defined(__NuttX__)
#define VLR_PLATFORM "nuttx"
#elif defined(__APPLE__)
#define VLR_PLATFORM "macos"
#elif defined(__linux__)
#define VLR_PLATFORM "linux"
#else
#define VLR_PLATFORM "posix"
#endif

lua_State *vlr_newstate(int dialect51, lua_Alloc alloc, void *ud)
{
    lua_State *L = alloc ? lua_newstate(alloc, ud) : luaL_newstate();

    if (L == NULL) return NULL;
    luaL_openlibs(L);
    lua_gc(L, LUA_GCINC, VLR_GC_PAUSE, VLR_GC_STEPMUL, 0);
    lua_getglobal(L, "os");
    lua_pushcfunction(L, l_exit);
    lua_setfield(L, -2, "exit");
    lua_pop(L, 1);
    vlr_modules_open(L);
    vlr_dotzero = !dialect51;
#if defined(VLR_LIBDIR) && defined(VLR_HOSTLIBDIR) && defined(__NuttX__)
    { /* simulator: no persistent storage, so a host directory is mounted as the library folder (hostfs) unless it exists */
        struct stat st;
        char path[] = VLR_LIBDIR, *p;

        if (stat(path, &st) != 0) {
            for (p = path + 1; (p = strchr(p, '/')) != NULL; *p++ = '/') { *p = '\0'; mkdir(path, 0755); }
            mkdir(path, 0755);
            mount("", path, "hostfs", 0, "fs=" VLR_HOSTLIBDIR);
        }
    }
#endif
#ifdef VLR_LIBDIR /* the target's library folder (vaporOS: /flash/lib), searched before the default path */
    lua_getglobal(L, "package");
    lua_pushliteral(L, VLR_LIBDIR "/?.lua;" VLR_LIBDIR "/?/init.lua;");
    lua_getfield(L, -2, "path");
    lua_concat(L, 2);
    lua_setfield(L, -2, "path");
    lua_pop(L, 1);
#else /* host builds: a project's own libraries, as installed by `vpm i` (like node_modules): ./lua_modules is searched before everything else */
    lua_getglobal(L, "package");
    lua_pushliteral(L, "./lua_modules/?.lua;./lua_modules/?/init.lua;");
    lua_getfield(L, -2, "path");
    lua_concat(L, 2);
    lua_setfield(L, -2, "path");
    lua_pushliteral(L, "./lua_modules/?.so;");
    lua_getfield(L, -2, "cpath");
    lua_concat(L, 2);
    lua_setfield(L, -2, "cpath");
    lua_pop(L, 1);
#endif

    lua_newtable(L); /* vapor */
    lua_pushcfunction(L, l_now);
    lua_setfield(L, -2, "now");
    lua_pushcfunction(L, l_wait);
    lua_setfield(L, -2, "wait");
    setcaps(L);
    lua_pushstring(L, dialect51 ? "5.1" : "5.4");
    lua_setfield(L, -2, "dialect");
    lua_pushstring(L, VLR_VERSION);
    lua_setfield(L, -2, "version");
    lua_pushstring(L, VLR_PLATFORM);
    lua_setfield(L, -2, "platform");
    lua_newtable(L); /* builtin: set of compiled-in module names, so a package manager knows what is already satisfied */
    {
        const char *const *b;

        for (b = vlr_builtin; *b != NULL; b++) {
            lua_pushboolean(L, 1);
            lua_setfield(L, -2, *b);
        }
    }
    lua_setfield(L, -2, "builtin");
    lua_setglobal(L, "vapor");

    if ((dialect51 && runembedded(L, vlr_lua_compat, vlr_lua_compat_len, "=compat")) ||
        runembedded(L, vlr_lua_sched, vlr_lua_sched_len, "=sched")) {
        /* embedded code failing is a build bug: say so and give up */
        fprintf(stderr, "vlr: internal error: %s\n", lua_tostring(L, -1));
        lua_close(L);
        return NULL;
    }
    return L;
}

int vlr_spawn_file(lua_State *L, const char *path, int argc, char **argv)
{
    int i;

    if (luaL_loadfile(L, path) != LUA_OK) {
        fprintf(stderr, "vlr: %s\n", lua_tostring(L, -1));
        lua_pop(L, 1);
        return 1;
    }
    lua_newtable(L); /* arg */
    lua_pushstring(L, path);
    lua_rawseti(L, -2, 0);
    for (i = 0; i < argc; i++) {
        lua_pushstring(L, argv[i]);
        lua_rawseti(L, -2, i + 1);
    }
    lua_setglobal(L, "arg");

    lua_getglobal(L, "vapor");
    lua_getfield(L, -1, "spawn");
    lua_remove(L, -2);
    lua_insert(L, -2); /* spawn, fn */
    for (i = 0; i < argc; i++) lua_pushstring(L, argv[i]);
    if (lua_pcall(L, 1 + argc, 0, 0) != LUA_OK) {
        fprintf(stderr, "vlr: %s\n", lua_tostring(L, -1));
        lua_pop(L, 1);
        return 1;
    }
    return 0;
}

int vlr_spawn_string(lua_State *L, const char *code, int argc, char **argv)
{
    int i;

    if (luaL_loadbuffer(L, code, strlen(code), "=(command line)") != LUA_OK) {
        fprintf(stderr, "vlr: %s\n", lua_tostring(L, -1));
        lua_pop(L, 1);
        return 1;
    }
    lua_newtable(L); /* arg: [0] is the program, like lua -e */
    lua_pushliteral(L, "vlr");
    lua_rawseti(L, -2, 0);
    for (i = 0; i < argc; i++) {
        lua_pushstring(L, argv[i]);
        lua_rawseti(L, -2, i + 1);
    }
    lua_setglobal(L, "arg");
    lua_getglobal(L, "vapor");
    lua_getfield(L, -1, "spawn");
    lua_remove(L, -2);
    lua_insert(L, -2);
    if (lua_pcall(L, 1, 0, 0) != LUA_OK) {
        fprintf(stderr, "vlr: %s\n", lua_tostring(L, -1));
        lua_pop(L, 1);
        return 1;
    }
    return 0;
}

int vlr_step(lua_State *L, int max_ms, int *next_ms)
{
    int r;

    lua_getglobal(L, "vapor");
    lua_getfield(L, -1, "step");
    lua_remove(L, -2);
    if (max_ms >= 0) lua_pushinteger(L, max_ms);
    else lua_pushnil(L);
    if (lua_pcall(L, 1, 1, 0) != LUA_OK) {
        fprintf(stderr, "vlr: %s\n", lua_tostring(L, -1));
        lua_pop(L, 1);
        return -1;
    }
    r = !lua_isnil(L, -1);
    if (r && next_ms != NULL) *next_ms = (int)lua_tointeger(L, -1);
    lua_pop(L, 1);
    return r;
}

int vlr_failed(lua_State *L)
{
    int r;

    lua_getglobal(L, "vapor");
    lua_getfield(L, -1, "failed");
    lua_remove(L, -2);
    lua_call(L, 0, 1);
    r = lua_toboolean(L, -1);
    lua_pop(L, 1);
    return r;
}

int vlr_run_file(lua_State *L, const char *path, int argc, char **argv)
{
    int r;

    if (vlr_spawn_file(L, path, argc, argv) != 0) return 1;
    while ((r = vlr_step(L, -1, NULL)) > 0) {}
    return r < 0 || vlr_failed(L);
}
